/// Iterate all Annex B records in category and runtime order.
pub fn annex_b_records() -> impl Iterator<Item = &'static AnnexBRecord> {
    ANNEX_B_IA
        .iter()
        .chain(ANNEX_B_ID)
        .chain(ANNEX_B_IE)
        .chain(ANNEX_B_IL)
        .chain(ANNEX_B_IS)
        .chain(ANNEX_B_IV)
        .chain(ANNEX_B_IW)
}

/// Look up one exact Annex B singleton identifier.
#[must_use]
pub fn annex_b_by_id(id: &str) -> Option<&'static AnnexBRecord> {
    let category = match id.get(..2) {
        Some("IA") => ANNEX_B_IA,
        Some("ID") => ANNEX_B_ID,
        Some("IE") => ANNEX_B_IE,
        Some("IL") => ANNEX_B_IL,
        Some("IS") => ANNEX_B_IS,
        Some("IV") => ANNEX_B_IV,
        Some("IW") => ANNEX_B_IW,
        _ => return None,
    };
    category.iter().find(|record| record.id.as_str() == id)
}
